#!/usr/bin/env python3
"""Create one self-contained HTML page for listening to the four T1 mixes."""
from __future__ import annotations
import argparse, base64, html, json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
def data_uri(path:Path,mime:str)->str:
 return f"data:{mime};base64,"+base64.b64encode(path.read_bytes()).decode('ascii')
def main()->None:
 p=argparse.ArgumentParser(); p.add_argument('--preview-dir',type=Path,default=ROOT/'output/t1-voice-music-v1'); args=p.parse_args()
 out=args.preview_dir.resolve(); report=json.loads((out/'T1_voice_music_validation.json').read_text(encoding='utf-8'))
 cards=[]
 for item in report['variants']:
  track_id=item['pixabay_id']; title=item['title'].split(' — ')[0]
  cards.append(f'''<article class="card"><div class="head"><div><span class="id">#{track_id}</span><h2>{html.escape(title)}</h2><p>{html.escape(item['artist'])}</p></div><b class="pass">QC PASS</b></div><audio controls preload="metadata" src="{data_uri(out/f'T1_voice_music_{track_id}.mp3','audio/mpeg')}"></audio><div class="metrics"><span><b>{item['preview_mp4']['integrated_lufs']:.2f}</b> LUFS AAC</span><span><b>{item['preview_mp4']['true_peak_dbtp']:.2f}</b> dBTP</span><span><b>+{item['intelligibility_proxy']['aggregate_speech_to_music_db']:.2f}</b> dB voix/musique</span></div><p class="path">Vidéo : output/t1-voice-music-v1/T1_voice_music_{track_id}.mp4</p></article>''')
 rows=''.join(f"<tr><td>{c['scene']}</td><td>{c['start_s']:.2f} s</td><td>{c['end_s']:.2f} s</td><td>{html.escape(c['text'])}</td></tr>" for c in report['voice']['clips'])
 plot=data_uri(out/'T1_ducking_voice_timeline.png','image/png')
 css='''*{box-sizing:border-box}:root{--ink:#201d19;--muted:#6e665e;--card:#fffaf4;--red:#9b2d30;--teal:#16796f;--line:#ded2c5}body{margin:0;background:linear-gradient(150deg,#efe3d5,#f8f3ec 42%,#e9eee9);color:var(--ink);font:16px/1.45 system-ui,sans-serif}main{max-width:1120px;margin:auto;padding:40px 24px 70px}header{border-left:8px solid var(--red);padding:4px 0 6px 22px;margin-bottom:26px}h1{font-family:Georgia,serif;font-size:clamp(30px,5vw,52px);line-height:1.04;margin:0 0 8px}header p,.card p{margin:2px 0;color:var(--muted)}.notice{background:#153f3b;color:white;border-radius:14px;padding:16px 20px;margin:22px 0 24px}.notice b{color:#ffd58f}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.card{background:var(--card);border:1px solid var(--line);border-radius:18px;padding:20px;box-shadow:0 10px 25px #442b1810}.head{display:flex;justify-content:space-between;gap:12px;align-items:flex-start}.card h2{font-family:Georgia,serif;font-size:28px;margin:2px 0 0}.id{font-weight:800;font-size:12px;letter-spacing:.1em;color:var(--red)}.pass{white-space:nowrap;background:#dff3eb;color:#12664f;border-radius:999px;padding:6px 9px;font-size:11px}audio{width:100%;margin:18px 0 12px;accent-color:var(--red)}.metrics{display:flex;flex-wrap:wrap;gap:8px}.metrics span{background:#f1e8dc;border-radius:8px;padding:7px 9px;font-size:12px;color:#564c43}.metrics b{color:var(--teal)}.path{font:10px ui-monospace,monospace!important;overflow-wrap:anywhere;margin-top:14px!important}section{margin-top:34px}section h2{font:30px Georgia,serif;margin-bottom:12px}.plot{width:100%;display:block;border:1px solid var(--line);border-radius:16px;background:white}table{width:100%;border-collapse:collapse;background:var(--card);border-radius:14px;overflow:hidden}th,td{padding:11px 12px;text-align:left;border-bottom:1px solid var(--line);vertical-align:top}th{background:#332d27;color:white;font-size:12px;text-transform:uppercase}td:nth-child(-n+3){white-space:nowrap}footer{margin-top:30px;color:var(--muted);font-size:13px}@media(max-width:720px){.grid{grid-template-columns:1fr}main{padding:24px 14px 50px}.metrics{display:grid;grid-template-columns:1fr 1fr}table{font-size:13px}th,td{padding:9px 7px}}'''
 page=f'''<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>T1 — planche d’écoute</title><style>{css}</style></head><body><main><header><h1>Voix française × 4 musiques</h1><p>Planche d’écoute T1 · même voix, mêmes placements, seul le fond Afrobeat/Amapiano change.</p></header><div class="notice"><b>🎧 Écoute humaine requise.</b> Les quatre rendus ont passé le contrôle objectif. Écoutez idéalement au casque.</div><div class="grid">{''.join(cards)}</div><section><h2>Comportement du ducking</h2><img class="plot" alt="Tige voix et courbe de ducking" src="{plot}"><p>Musique à −3 dB hors parole, −10 dB sous la voix, attaque 120 ms, relâchement 450 ms. Aucun SFX.</p></section><section><h2>Texte et placement</h2><table><thead><tr><th>Scène</th><th>Début</th><th>Fin</th><th>Voix off</th></tr></thead><tbody>{rows}</tbody></table></section><footer>QC : 30,000 s par vidéo · 48 kHz stéréo · zéro écrêtage · quatre variantes exactement.</footer></main><script>const a=[...document.querySelectorAll('audio')];a.forEach(p=>p.addEventListener('play',()=>a.forEach(q=>{{if(q!==p)q.pause()}})));</script></body></html>'''
 target=out/'T1_voice_music_listening_board.html'; target.write_text(page,encoding='utf-8'); print(target)
if __name__=='__main__': main()
